//! Family G: the generated scenario family of `docs/experiments/p2-protocol.md` §7.1.
//!
//! Development block: seeds 0–199. Held-out block *b* (b ≥ 1): seeds `10_000·b … 10_000·b +
//! 199`. Held-out instances must only be generated by the held-out phase (§7.2); nothing else,
//! including tests, may call [`instance`] with a held-out seed.
//!
//! The class is `seed mod 5`. Every instance parameter is drawn from `SplitMix64(seed)` in the
//! order listed for its class (Amendment 1, item 5). `U[a, b]` is `a + (b − a)·u` and
//! `U{a..b}` is `a + floor(u·(b − a + 1))`, with `u = next_f64()`.

use std::ops::Range;

use super::{Scenario, ScriptedProcessor, stream_chunks};
use crate::metrics::{CriticalStream, GroundTruth};
use crate::rng::SplitMix64;
use crate::workspace::{ProcessorId, Tick};

pub const NAME: &str = "family_g";
pub const HORIZON: u64 = 200;

/// Development block seeds.
pub const DEV_SEEDS: Range<u64> = 0..200;

/// Seeds of held-out block `b` (b ≥ 1). Each block is used once (§7.2).
///
/// # Panics
///
/// If `b == 0`: block 0 does not exist, the development block is [`DEV_SEEDS`].
pub fn heldout_block(b: u64) -> Range<u64> {
    assert!(b >= 1, "held-out blocks start at 1");
    10_000 * b..10_000 * b + 200
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum GClass {
    C1Onset,
    C2SilentOnset,
    C3Transient,
    C4Stable,
    C5NoisyStable,
}

impl GClass {
    pub const ALL: [GClass; 5] = [
        GClass::C1Onset,
        GClass::C2SilentOnset,
        GClass::C3Transient,
        GClass::C4Stable,
        GClass::C5NoisyStable,
    ];

    pub fn of_seed(seed: u64) -> GClass {
        GClass::ALL[(seed % 5) as usize]
    }

    /// C1–C3 have one critical stream; C4–C5 have none.
    pub fn is_critical(self) -> bool {
        matches!(
            self,
            GClass::C1Onset | GClass::C2SilentOnset | GClass::C3Transient
        )
    }

    pub fn label(self) -> &'static str {
        match self {
            GClass::C1Onset => "C1",
            GClass::C2SilentOnset => "C2",
            GClass::C3Transient => "C3",
            GClass::C4Stable => "C4",
            GClass::C5NoisyStable => "C5",
        }
    }
}

/// Neutral payload labels, indexed by processor id (at most 13 processors per instance).
const LABELS: [&str; 16] = [
    "A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L", "M", "N", "O", "P",
];

fn real(rng: &mut SplitMix64, a: f64, b: f64) -> f64 {
    a + (b - a) * rng.next_f64()
}

fn int(rng: &mut SplitMix64, a: u64, b: u64) -> u64 {
    (a + (rng.next_f64() * (b - a + 1) as f64) as u64).min(b)
}

fn constant(id: u32, weight: f64) -> Box<dyn crate::workspace::Processor> {
    ScriptedProcessor::boxed(ProcessorId(id), LABELS[id as usize], move |_| Some(weight))
}

/// Builds instance `seed` of family G and returns it with its class.
pub fn instance(seed: u64) -> (Scenario, GClass) {
    let class = GClass::of_seed(seed);
    let mut rng = SplitMix64::new(seed);
    let mut processors = Vec::new();
    let mut streams = Vec::new();

    match class {
        GClass::C1Onset | GClass::C2SilentOnset => {
            // Order: n_bg, background weights, w_d, [w_pre for C1 only], T_on, g.
            let n_bg = int(&mut rng, 1, 6) as u32;
            let bg: Vec<f64> = (0..n_bg).map(|_| real(&mut rng, 0.1, 0.5)).collect();
            let w_d = real(&mut rng, 0.75, 0.95);
            let w_pre = (class == GClass::C1Onset).then(|| real(&mut rng, 0.1, 0.4));
            let t_on = int(&mut rng, 30, 150);
            let g = real(&mut rng, 0.15, 0.45);
            let w_crit = w_d - g;

            processors.push(constant(0, w_d));
            for (i, &w) in bg.iter().enumerate() {
                processors.push(constant(1 + i as u32, w));
            }
            let crit = ProcessorId(n_bg + 1);
            processors.push(ScriptedProcessor::boxed(
                crit,
                LABELS[crit.0 as usize],
                move |t: Tick| {
                    if t >= t_on { Some(w_crit) } else { w_pre }
                },
            ));
            streams.push(CriticalStream {
                name: format!("{} from t={t_on}", LABELS[crit.0 as usize]),
                chunks: stream_chunks(crit, t_on..HORIZON),
            });
        }
        GClass::C3Transient => {
            // Order: n_bg, background weights, w_d, m, T_on, g.
            let n_bg = int(&mut rng, 3, 10) as u32;
            let bg: Vec<f64> = (0..n_bg).map(|_| real(&mut rng, 0.1, 0.5)).collect();
            let w_d = real(&mut rng, 0.75, 0.95);
            let m = int(&mut rng, 3, 12);
            let t_on = int(&mut rng, 30, 150);
            let g = real(&mut rng, 0.15, 0.45);
            let w_crit = w_d - g;
            let window = t_on..t_on + m;

            processors.push(constant(0, w_d));
            for (i, &w) in bg.iter().enumerate() {
                processors.push(constant(1 + i as u32, w));
            }
            let crit = ProcessorId(n_bg + 1);
            let active = window.clone();
            processors.push(ScriptedProcessor::boxed(
                crit,
                LABELS[crit.0 as usize],
                move |t: Tick| active.contains(&t).then_some(w_crit),
            ));
            streams.push(CriticalStream {
                name: format!(
                    "{} during t={}..{}",
                    LABELS[crit.0 as usize], window.start, window.end
                ),
                chunks: stream_chunks(crit, window),
            });
        }
        GClass::C4Stable => {
            // Order: w_d, n_bg, background weights.
            let w_d = real(&mut rng, 0.75, 0.95);
            let n_bg = int(&mut rng, 2, 12) as u32;
            processors.push(constant(0, w_d));
            for i in 0..n_bg {
                let w = real(&mut rng, 0.1, 0.5);
                processors.push(constant(1 + i, w));
            }
        }
        GClass::C5NoisyStable => {
            // Order: w_d, n_bg, then one seed per fluctuating source (next_u64).
            let w_d = real(&mut rng, 0.75, 0.95);
            let n_bg = int(&mut rng, 2, 8) as u32;
            processors.push(constant(0, w_d));
            for i in 0..n_bg {
                let mut source_rng = SplitMix64::new(rng.next_u64());
                let id = 1 + i;
                // `propose` is called exactly once per tick, so one draw per call is one
                // fresh weight per tick.
                processors.push(ScriptedProcessor::boxed(
                    ProcessorId(id),
                    LABELS[id as usize],
                    move |_| Some(real(&mut source_rng, 0.1, 0.6)),
                ));
            }
        }
    }

    let scenario = Scenario {
        name: NAME,
        description: "generated family G instance (p2-protocol.md §7.1)",
        horizon: HORIZON,
        held_out: !DEV_SEEDS.contains(&seed),
        processors,
        truth: GroundTruth { streams },
    };
    (scenario, class)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn heldout_block_ranges() {
        assert_eq!(heldout_block(1), 10_000..10_200);
        assert_eq!(heldout_block(2), 20_000..20_200);
        assert!(heldout_block(1).start >= DEV_SEEDS.end);
    }

    #[test]
    #[should_panic(expected = "held-out blocks start at 1")]
    fn block_zero_does_not_exist() {
        let _ = heldout_block(0);
    }

    #[test]
    fn integer_draws_cover_both_ends() {
        let mut rng = SplitMix64::new(3);
        let draws: Vec<u64> = (0..2000).map(|_| int(&mut rng, 3, 12)).collect();
        assert_eq!(*draws.iter().min().unwrap(), 3);
        assert_eq!(*draws.iter().max().unwrap(), 12);
    }

    #[test]
    fn class_is_seed_mod_5() {
        assert_eq!(GClass::of_seed(0), GClass::C1Onset);
        assert_eq!(GClass::of_seed(7), GClass::C3Transient);
        assert_eq!(GClass::of_seed(199), GClass::C5NoisyStable);
    }
}
